/* Flashcard. f = fronte, b = retro, a = argomento, l = lezione,
   c = capitolo del manuale, t = tipo (definizione|formula|data|coppia|elenco|perche) */
var PGE = window.PGE = window.PGE || {};

PGE.flashcard = [
/* --- DEFINIZIONE --- */
{f:"Etimologia di «psicologia»",b:"Dal greco <em>psyché</em> (anima) + <em>lógos</em> (discorso): «discorso sull'anima», cioè <strong>scienza della mente</strong>.",a:"Definizione",l:"L01",c:"C01",t:"definizione"},
{f:"La definizione <em>generale</em> di psicologia",b:"Studio scientifico della <strong>mente</strong> e del <strong>comportamento</strong>.<br><em>Attenzione: il docente la dichiara volutamente vaga.</em>",a:"Definizione",l:"L01",c:"C01",t:"formula"},
{f:"La definizione <em>attuale e completa</em> — alla lettera",b:"Studio scientifico del <strong>comportamento e dei processi mentali dell'essere vivente nel suo rapporto con l'ambiente: mentre lo esperisce, vi agisce e lo rappresenta</strong>.",a:"Definizione",l:"L01",c:"C01",t:"formula"},
{f:"Mente — definizione e caratteri",b:"L'esperienza <strong>interiore</strong> personale: percezioni, pensieri, ricordi, sentimenti. Soggettiva, non osservabile direttamente; genera il <strong>flusso di coscienza</strong>.",a:"Definizione",l:"L01",c:"C01",t:"definizione"},
{f:"Comportamento — definizione e caratteri",b:"Le azioni degli <strong>esseri umani e degli animali non umani</strong>. Esterno, <strong>direttamente osservabile</strong>.<br><em>Mai dire «dell'uomo».</em>",a:"Definizione",l:"L01",c:"C01",t:"definizione"},
{f:"Perché «e degli animali non umani»?",b:"Perché la <strong>psicologia comparata</strong> è metodo elettivo della disciplina: senza gli animali non si spiegano Pavlov, Thorndike, Köhler, Watson, Skinner.",a:"Definizione",l:"L01",c:"C01",t:"perche"},
{f:"I tre verbi della definizione, e a che cosa corrispondono",b:"Lo <strong>esperisce</strong> (ricettivo: psicofisica, Gestalt) · vi <strong>agisce</strong> (attivo: funzionalismo, comportamentismo) · lo <strong>rappresenta</strong> (interno: Vygotskij, Tolman, cognitivismo).",a:"Definizione",l:"L01",c:"C01",t:"elenco"},
{f:"Che cosa rende «scientifico» lo studio della mente?",b:"Non l'oggetto ma il <strong>metodo</strong>: il metodo sperimentale con <strong>verifica empirica</strong>, contro la speculazione da assiomi indimostrabili. Svolta: <strong>1879</strong>.",a:"Definizione",l:"L01",c:"C01",t:"perche"},
{f:"La terna con cui si valuta ogni scuola",b:"<strong>Oggetto → metodo → validità.</strong> Che cosa studia, come lo studia, se il come regge. Nella maggior parte dei casi la scuola muore per il <strong>secondo</strong> termine.",a:"Definizione",l:"L01",c:"C01",t:"elenco"},

/* --- RITARDO --- */
{f:"Le tre cause del ritardo della psicologia",b:"1. Difficoltà di <strong>definire l'oggetto</strong><br>2. Difficoltà di considerare l'<strong>uomo</strong> oggetto di studio scientifico<br>3. Concezione <strong>trascendentale</strong> della mente",a:"Definizione",l:"L01",c:"C02",t:"elenco"},
{f:"Emancipazione dalla <strong>filosofia</strong> — formula completa",b:"Dallo studio della mente sul <strong>piano filosofico</strong> → allo studio della <strong>relazione mente-corpo sul piano naturalistico</strong>.",a:"Definizione",l:"L01",c:"C02",t:"formula"},
{f:"Emancipazione dalla <strong>medicina</strong> — formula completa",b:"Dallo studio del cervello sul <strong>piano meramente fisiologico</strong> → allo studio dell'<strong>unità cervello-mente e delle sue interazioni con l'ambiente</strong>.",a:"Definizione",l:"L01",c:"C02",t:"formula"},
{f:"Perché non basta dire «prima non si studiava il cervello»?",b:"Il cervello <strong>era già</strong> studiato scientificamente, come organo. Mancava il <strong>ponte concettuale</strong>: concepire che la mente fosse determinata dal funzionamento del cervello.",a:"Definizione",l:"L01",c:"C02",t:"perche"},
{f:"Metodo razionalista vs metodo sperimentale",b:"<strong>Razionalista</strong>: speculazione logica da <strong>assiomi indimostrabili</strong>, nessuna verifica.<br><strong>Sperimentale</strong>: <strong>verifica empirica</strong> tangibile, sul modello di chimica e fisica.",a:"Definizione",l:"L01",c:"C02",t:"coppia"},
{f:"Perché il positivismo da solo non basta?",b:"È un'<strong>affermazione di principio</strong>: dice che la psicologia <em>dovrebbe</em> essere scienza. Serve la <strong>psicofisica</strong> a dimostrare che un fenomeno psichico <em>può</em> essere misurato.",a:"Definizione",l:"L01",c:"C02",t:"perche"},

/* --- PRE-SCIENTIFICA --- */
{f:"Trapanazione",b:"Guaritori antichi: pietre grezze sfregate sulla <strong>scatola cranica</strong> dei «posseduti» per far uscire gli spiriti. Nessun fondamento, spesso letale.",a:"Pre-scientifica",l:"L01",c:"C03",t:"definizione"},
{f:"Ippocrate — contributo",b:"Prima <strong>teoria della personalità</strong> della storia occidentale: i <strong>quattro temperamenti</strong>. Sposta la causa dei disturbi dagli spiriti al corpo.",a:"Pre-scientifica",l:"L01",c:"C03",t:"definizione"},
{f:"Cartesio — <em>res cogitans</em> e <em>res extensa</em>",b:"<strong>Res cogitans</strong>: la cosa pensante — spirito, anima, mente.<br><strong>Res extensa</strong>: la materia, il corpo, <strong>cervello incluso</strong>.",a:"Pre-scientifica",l:"L01",c:"C03",t:"coppia"},
{f:"Cartesio — la ghiandola pineale",b:"Il <strong>punto di contatto</strong> attraverso cui l'energia raccolta dall'ambiente fluisce dal corpo nella <em>res cogitans</em>, dando luogo ai fenomeni psichici.",a:"Pre-scientifica",l:"L01",c:"C03",t:"definizione"},
{f:"Gall — la frenologia",b:"Le caratteristiche di personalità <strong>risiedono nel cervello</strong> e si desumono dalle <strong>protuberanze craniche</strong>. Nessun fondamento; ripresa da <strong>Lombroso</strong>.",a:"Pre-scientifica",l:"L01",c:"C03",t:"definizione"},
{f:"I due lasciti della fase pre-scientifica",b:"Da <strong>Cartesio</strong>: la separazione mente/corpo — <strong>da superare</strong>.<br>Da <strong>Gall</strong>: l'idea di <strong>localizzazione</strong> cerebrale — <strong>da recuperare</strong>.",a:"Pre-scientifica",l:"L01",c:"C03",t:"coppia"},

/* --- CONTESTO --- */
{f:"Comte — il positivismo",b:"Alle <strong>scienze naturali</strong> il ruolo privilegiato di <strong>unica fonte attendibile di conoscenza</strong>. Ogni disciplina, per produrre conoscenza, deve avere base scientifica.",a:"Nascita",l:"L01",c:"C04",t:"definizione"},
{f:"Psicofisica — definizione tecnica",b:"Studio di come le <strong>sensazioni percepite a livello psicologico dipendano dalle caratteristiche fisiche degli stimoli ambientali</strong>. <strong>Precursore diretto</strong> della psicologia scientifica.",a:"Nascita",l:"L01",c:"C04",t:"definizione"},
{f:"Fechner — l'affermazione fondativa",b:"La <strong>sensazione</strong> è <strong>oggettiva, materiale e misurabile</strong>. Traduce matematicamente il rapporto fisico/psichico: <strong>legge di Weber-Fechner</strong>.",a:"Nascita",l:"L01",c:"C04",t:"formula"},
{f:"von Helmholtz — teoria dell'inferenza inconscia",b:"La percezione è un <strong>processo costruttivo</strong>, influenzata e corretta dall'<strong>esperienza pregressa</strong> tramite un processo cognitivo <strong>inconsapevole</strong>.",a:"Nascita",l:"L01",c:"C04",t:"definizione"},
{f:"Dove ritorna l'inferenza inconscia?",b:"Nella <strong>Gestalt</strong> (che la radicalizza: leggi <em>innate</em> invece di esperienza), nel <strong>cognitivismo</strong>, e nella psicologia della percezione (L16-L17).",a:"Nascita",l:"L01",c:"C04",t:"perche"},

/* --- WUNDT --- */
{f:"L'atto di nascita della psicologia scientifica",b:"<strong>Wundt</strong>, <strong>Lipsia</strong>, <strong>1879</strong>: primo laboratorio di <strong>Psicologia Fisiologica</strong>.",a:"Nascita",l:"L01",c:"C05",t:"data"},
{f:"Wundt — oggetto di studio",b:"L'<strong>esperienza diretta e immediata</strong> — contenuto della coscienza dell'attività mentale consapevole — <strong>scomposta negli elementi irriducibili</strong>, gli «<strong>atomi della mente</strong>».",a:"Nascita",l:"L01",c:"C05",t:"formula"},
{f:"Wundt — l'analogia guida",b:"Come la <strong>chimica</strong> studia la materia scomponendola in <strong>atomi</strong>, così la psicologia studia la coscienza scomponendola in elementi semplici.",a:"Nascita",l:"L01",c:"C05",t:"definizione"},
{f:"I quattro vincoli del metodo introspettivo",b:"1. Soggetto = <strong>sperimentatore addestrato</strong><br>2. Criteri <strong>elementistici</strong>, congruenti con le proprietà fisiche<br>3. Esperienza <strong>immediata</strong>, non l'interpretazione<br>4. Misura dei <strong>tempi di reazione</strong>",a:"Nascita",l:"L01",c:"C05",t:"elenco"},
{f:"Tempi di reazione — che cosa indicano",b:"Più il tempo di reazione è <strong>lungo</strong>, più è probabile che il soggetto stia <strong>interpretando</strong> anziché riferire il contenuto irriducibile della coscienza.",a:"Nascita",l:"L01",c:"C05",t:"formula"},
{f:"Perché «c'è scritta una parola» viola il metodo?",b:"Perché è <strong>già un'interpretazione</strong>: si è attribuita allo stimolo la categoria «parola». Bisogna fermarsi ai segni, alle forme, alle tonalità.",a:"Nascita",l:"L01",c:"C05",t:"perche"},
{f:"Che cosa fonda davvero Wundt?",b:"Non una teoria destinata a durare, ma la <strong>psicologia come pratica sperimentale istituzionalizzata</strong>: il laboratorio, il tirocinio, la figura dello psicologo sperimentale.",a:"Nascita",l:"L01",c:"C05",t:"perche"},

/* --- STRUTTURALISMO --- */
{f:"Strutturalismo — chi, dove, quando",b:"<strong>Titchener</strong>, <strong>Cornell University</strong>, <strong>1892</strong>. Allievo di Wundt: porta in America la psicologia wundtiana, le dà un nome e la sistematizza.",a:"Strutturalismo",l:"L01",c:"C06",t:"data"},
{f:"Strutturalismo — perché si chiama così",b:"Perché l'oggetto è la <strong>struttura</strong> della mente e della coscienza, colta nei suoi elementi irriducibili.",a:"Strutturalismo",l:"L01",c:"C06",t:"perche"},
{f:"Strutturalismo — oggetto di studio",b:"<strong>Percezioni, emozioni (o sentimenti) e idee</strong>, analizzate attraverso i rispettivi <strong>elementi più semplici</strong>.",a:"Strutturalismo",l:"L01",c:"C06",t:"formula"},
{f:"Titchener — mente vs coscienza",b:"<strong>Mente</strong>: somma di <strong>tutti</strong> i processi mentali di una vita.<br><strong>Coscienza</strong>: somma dei processi <em>hic et nunc</em>.<br>La mente è la biografia, la coscienza è l'istante.",a:"Strutturalismo",l:"L01",c:"C06",t:"coppia"},
{f:"Strutturalismo — il metodo",b:"Introspezione <strong>ancora più sistematizzata</strong>: un <strong>vocabolario</strong> obbligatorio per il soggetto. <strong>[slide]</strong> Furono individuate <strong>44.000 unità sensoriali</strong>.",a:"Strutturalismo",l:"L01",c:"C06",t:"definizione"},
{f:"Le DUE critiche al metodo introspettivo",b:"1. <strong>Retrospezione</strong> — problema di <strong>tempo</strong>: fra percezione e verbalizzazione passa del tempo, l'immediatezza si perde.<br>2. <strong>Incoerenza dei resoconti</strong> — problema di <strong>attendibilità</strong>: soggetti addestrati descrivono in modo incoerente gli stessi stimoli.",a:"Strutturalismo",l:"L01",c:"C06",t:"coppia"},
{f:"Strutturalismo — il merito storico",b:"Aver posto la <strong>questione del metodo</strong> come condizione perché la psicologia diventi scienza. La domanda giusta resta giusta anche quando la risposta è sbagliata.",a:"Strutturalismo",l:"L01",c:"C06",t:"perche"},
{f:"Strutturalismo — l'esito",b:"Con la <strong>morte di Titchener (1927)</strong> la scuola <strong>decade</strong>: era tenuta insieme dalla persona che l'aveva sistematizzata. Fornisce però l'input al funzionalismo.",a:"Strutturalismo",l:"L01",c:"C06",t:"data"},
{f:"L'esigenza che porta al funzionalismo",b:"Andare <strong>oltre la struttura</strong>: considerare la mente <strong>all'interno dell'ambiente</strong> in cui l'individuo vive, e non per i contenuti ma per le <strong>funzioni</strong>.<br><em>È una critica all'oggetto, non al metodo.</em>",a:"Strutturalismo",l:"L01",c:"C06",t:"perche"},

/* --- FUNZIONALISMO --- */
{f:"Funzionalismo — la tesi centrale",b:"I fenomeni mentali sono <strong>funzioni</strong>, non contenuti psichici. Nuovo interrogativo: <strong>a che cosa servono e come funzionano</strong> i processi mentali?",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"Darwin — la selezione naturale",b:"Le caratteristiche più <strong>utili alla sopravvivenza</strong> e alla riproduzione hanno <strong>maggiori probabilità di essere trasmesse alle generazioni successive</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"Il concetto darwiniano che passa al funzionalismo",b:"L'<strong>adattamento all'ambiente</strong>. Sopravvivono solo gli individui che meglio si adattano — e finirà nella definizione moderna della disciplina.",a:"Funzionalismo",l:"L01",c:"C07",t:"perche"},
{f:"James — lo <em>stream of consciousness</em>",b:"La coscienza non è una serie di elementi distinti ma un <strong>flusso dinamico</strong>, un fiume che scorre: nessun momento di coscienza è <strong>replicabile</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"definizione"},
{f:"James — la conclusione dell'argomento",b:"Se i contenuti sono continuamente mutevoli, studiarli è privo di senso: <strong>è più utile studiare come la mente funziona che come è fatta</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"James — la mente e l'adattamento",b:"La mente è l'<strong>effetto massimo dell'adattamento</strong> finalizzato all'<strong>autoconservazione</strong>: la struttura più evoluta dell'uomo, quella che gli consente di adattarsi meglio.",a:"Funzionalismo",l:"L01",c:"C07",t:"definizione"},
{f:"I caposcuola del funzionalismo",b:"<strong>Dewey, Angell, Carr</strong> — <strong>Scuola di Chicago</strong>, <strong>1896</strong>. Emettono il <strong>manifesto funzionalista</strong>.<br><em>James è precursore, non caposcuola.</em>",a:"Funzionalismo",l:"L01",c:"C07",t:"data"},
{f:"Funzionalismo — oggetto di studio",b:"Le <strong>attività mentali</strong> e la loro <strong>utilizzazione nella guida del comportamento</strong>: i comportamenti nella loro <strong>globalità</strong>, in relazione all'<strong>adattamento ambientale</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"Funzionalismo — il metodo",b:"<strong>Eclettico</strong> ma sperimentale: laboratorio, osservazione semplice, osservazione controllata.<br><em>Non è vaghezza: se l'oggetto è un rapporto, il metodo deve seguirlo dove si dà.</em>",a:"Funzionalismo",l:"L01",c:"C07",t:"definizione"},
{f:"Thorndike — il connessionismo",b:"I processi psichici sono <strong>connessioni, innate o acquisite, fra una situazione e una risposta</strong>. È già in sostanza lo schema <strong>S-R</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"La legge dell'effetto",b:"Un comportamento seguito da <strong>feedback positivo</strong> si <strong>rinforza</strong> e diventa più probabile; seguito da <strong>feedback negativo</strong> tende a <strong>estinguersi</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"formula"},
{f:"Perché la lezione isola Thorndike?",b:"Non perché sia caposcuola — non lo è — ma perché interpreta il funzionalismo in modo <strong>originale</strong> e diventa <strong>precursore diretto del comportamentismo</strong>.",a:"Funzionalismo",l:"L01",c:"C07",t:"perche"},

/* --- SCUOLE RUSSE --- */
{f:"In che senso le scuole russe sono «collaterali»?",b:"In senso <strong>geografico e istituzionale</strong>: fuori dall'asse accademico Germania-America.<br><em>NON isolate dalle idee, NON meno scientifiche: Pavlov è Nobel 1904.</em>",a:"Scuole collaterali",l:"L01",c:"C08",t:"perche"},
{f:"Lo spartiacque delle scuole russe",b:"La <strong>rivoluzione russa del 1917</strong>: divide la <strong>scuola riflessologica</strong> (prima) dalla <strong>scuola storico-culturale</strong> (dopo).",a:"Scuole collaterali",l:"L01",c:"C08",t:"data"},
{f:"Riflessologia — la tesi",b:"I processi psichici sono <strong>riducibili a riflessi</strong>, cioè a processi puramente <strong>fisiologici ed elementari</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"formula"},
{f:"Che cos'è un riflesso?",b:"Meccanismo di <strong>connessione fra due o più neuroni</strong> — uno in input, uno in output — che riceve uno stimolo e produce una risposta. Carattere distintivo: l'<strong>automaticità</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"definizione"},
{f:"Riflessi spinali vs cerebrali",b:"<strong>Spinali</strong>: sede nel <strong>midollo spinale</strong>, nessuna consapevolezza (es. riflesso patellare).<br><strong>Cerebrali</strong>: stazioni del circuito <strong>nel cervello</strong>, mediano comportamenti leggermente più complessi.",a:"Scuole collaterali",l:"L01",c:"C08",t:"coppia"},
{f:"Pavlov — la scoperta",b:"Studiando le secrezioni salivari di cani affamati, osserva che salivano anche <strong>alla sola vista dell'inserviente senza cibo</strong>: il riflesso si attiva davanti a uno stimolo che <strong>in natura non lo provoca</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"definizione"},
{f:"Teoria dei riflessi condizionati (1902) — alla lettera",b:"I riflessi condizionati costituiscono una <strong>forma elementare di apprendimento</strong>, fondata sull'<strong>associazione fra due stimoli</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"formula"},
{f:"Per che cosa Pavlov vince il Nobel nel 1904?",b:"Per gli studi sulla <strong>digestione</strong>, non sui riflessi condizionati. La scoperta che interessa la psicologia arriva come <strong>sottoprodotto</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"data"},
{f:"Perché Pavlov è precursore e non comportamentista?",b:"Perché è un <strong>fisiologo</strong>: parla di riflessi e circuiti nervosi, non costruisce una teoria psicologica generale. Il comportamentismo prende il suo <strong>paradigma sperimentale</strong>.",a:"Scuole collaterali",l:"L01",c:"C08",t:"perche"},
{f:"Vygotskij — lo spostamento di attenzione",b:"Dai <strong>processi semplici</strong> (contenuti di coscienza, associazioni elementari) → alla <strong>dimensione sociale</strong> dell'essere umano e alle <strong>funzioni complesse</strong> della mente.",a:"Scuole collaterali",l:"L01",c:"C08",t:"formula"},
{f:"Vygotskij — la tesi centrale",b:"Lo sviluppo della psiche è connesso agli <strong>stadi dello sviluppo socio-economico</strong>: più la società è stimolante, più si sviluppano funzioni mentali complesse.",a:"Scuole collaterali",l:"L01",c:"C08",t:"formula"},
{f:"Vygotskij — il linguaggio",b:"È l'<strong>espressione principale della vita psichica umana</strong> ed è <strong>alla base dei processi di coscienza</strong>. Non veicola il pensiero: lo struttura.",a:"Scuole collaterali",l:"L01",c:"C08",t:"formula"},
{f:"Le DUE ragioni dell'importanza di Vygotskij",b:"1. Mostra come il <strong>pensiero scientifico risenta della società</strong> in cui nasce.<br>2. È <strong>precursore del cognitivismo</strong>.<br><em>Servono entrambe.</em>",a:"Scuole collaterali",l:"L01",c:"C08",t:"elenco"},
{f:"Il nome corretto della scuola di Vygotskij",b:"Scuola <strong>storico</strong>-culturale — non «socio-culturale». La tesi riguarda gli stadi <strong>storici</strong> dello sviluppo socio-economico.",a:"Scuole collaterali",l:"L01",c:"C08",t:"definizione"},

/* --- PSICOANALISI --- */
{f:"Psicoanalisi — il tratto che la distingue da tutte",b:"<strong>Non nasce in ambiente accademico</strong>, ma dalla sistemazione teorica di <strong>esperienze cliniche</strong> (nevrosi isterica trattata con tecniche ipnotiche).",a:"Psicoanalisi",l:"L01",c:"C09",t:"perche"},
{f:"Le tre conseguenze epistemologiche della psicoanalisi",b:"1. Nessuna <strong>metodologia sperimentale</strong><br>2. Procede per <strong>speculazione logica</strong><br>3. Conoscenza <strong>non verificabile empiricamente</strong>",a:"Psicoanalisi",l:"L01",c:"C09",t:"elenco"},
{f:"I DUE postulati di Freud",b:"1. Un'<strong>unità di funzionamento mente-corpo</strong><br>2. Una <strong>pluralità di livelli</strong> di funzione mentale: inconscio, preconscio, conscio",a:"Psicoanalisi",l:"L01",c:"C09",t:"elenco"},
{f:"Perché si dice «dinamica»?",b:"Il termine fa riferimento a una <strong>relazione mobile fra le parti funzionali della mente</strong>: inconscio, preconscio e conscio <strong>interagiscono dinamicamente</strong>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"perche"},
{f:"I tre livelli di funzionamento mentale",b:"<strong>Inconscio</strong> (non consapevole) · <strong>preconscio</strong> (intermedio, accessibile) · <strong>conscio</strong> (consapevole).<br><strong>[slide]</strong> Poi: <strong>Es, Io, Super-Io</strong>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"elenco"},
{f:"Che cosa apprende Freud da Charcot?",b:"A <strong>Parigi</strong>, Charcot trattava con l'<strong>ipnosi</strong> disturbi senza base organica: riemergevano contenuti inconsapevoli e <strong>il sintomo spariva</strong>. Da qui l'intuizione dell'inconscio.",a:"Psicoanalisi",l:"L01",c:"C09",t:"definizione"},
{f:"Il metodo psicoanalitico — le quattro vie",b:"<strong>Libere associazioni</strong> · <strong>interpretazione dei sogni</strong> (contenuto latente → manifesto) · <strong>atti mancati e lapsus</strong> · <strong>sintomi</strong>.<br><em>Freud abbandona l'ipnosi.</em>",a:"Psicoanalisi",l:"L01",c:"C09",t:"elenco"},
{f:"Psicoanalisi — oggetto di studio",b:"Le <strong>istanze psichiche</strong> e le loro <strong>relazioni dinamiche</strong>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"formula"},
{f:"Il conflitto freudiano — i due termini",b:"<strong>Principio di piacere</strong> (bisogno di soddisfare il piacere interno) ⟷ <strong>principio di realtà</strong> (necessario confronto con il mondo reale, che spesso lo impedisce).",a:"Psicoanalisi",l:"L01",c:"C09",t:"coppia"},
{f:"Primo assunto fondamentale di Freud",b:"<strong>Continuità fra normalità e patologia</strong>: gli stessi processi spiegano il lapsus quotidiano e il sintomo clinico. Non frattura ma <em>continuum</em>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"formula"},
{f:"Secondo assunto fondamentale di Freud",b:"<strong>Ruolo centrale dell'inconscio</strong> — entità <strong>non osservabile direttamente</strong> — nel <strong>modulare l'attività conscia</strong>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"formula"},
{f:"Psicoanalisi — il bilancio",b:"<strong>Limite</strong>: fondazione epistemologica povera, nessun controllo della conoscenza.<br><strong>Merito</strong>: nuovi metodi di cura, prima teorizzazione dei disturbi psichici, teoria della personalità anche normale, influenza duratura.",a:"Psicoanalisi",l:"L01",c:"C09",t:"coppia"},
{f:"Freud e il comportamentismo: il contrasto",b:"Nascono negli stessi anni e rispondono in modo opposto alla stessa domanda — che cosa fare dell'<strong>inosservabile</strong>: il comportamentismo lo <strong>esclude</strong>, Freud lo mette al <strong>centro</strong>.",a:"Psicoanalisi",l:"L01",c:"C09",t:"coppia"},

/* --- GESTALT --- */
{f:"Il motto della Gestalt",b:"«Il <strong>tutto</strong> è più della <strong>somma delle parti</strong>».",a:"Gestalt",l:"L02",c:"C10",t:"formula"},
{f:"Gestalt — anno, luogo, bersaglio",b:"<strong>1912</strong>, <strong>Germania</strong>, contro <strong>Wundt</strong>, che sbaglia perché <strong>scompone</strong>. Seconda fioritura negli <strong>USA</strong> per il nazismo.",a:"Gestalt",l:"L02",c:"C10",t:"data"},
{f:"Kant — la sintesi a priori",b:"L'atto della conoscenza è un'<strong>attività unitaria e unificante</strong> in cui la <strong>materia</strong> fornita dai sensi è organizzata attraverso <strong>forme proprie della mente</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"formula"},
{f:"Kant — le idee a priori",b:"<strong>Schemi e regole innate</strong>, possedute alla nascita da ogni individuo della specie perché <strong>geneticamente predeterminate</strong>, responsabili dell'atto unificante.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Brentano — la psicologia dell'atto",b:"Oggetto della psicologia è l'<strong>atto</strong>; ma l'atto <strong>ha senso solo in riferimento a un oggetto</strong>. L'aspetto specifico dei fenomeni psichici è l'<strong>intenzionalità</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Fenomeno vs oggetto fisico",b:"<strong>Fenomeno</strong>: l'oggetto <strong>per come lo percepisco</strong>, esistente <em>dentro</em> il mio atto.<br><strong>Oggetto fisico</strong>: quello della realtà, indipendente da me.",a:"Gestalt",l:"L02",c:"C10",t:"coppia"},
{f:"Gli esponenti della Gestalt",b:"<strong>Wertheimer</strong> caposcuola. Allievi: <strong>Köhler</strong> e <strong>Koffka</strong>. A parte: <strong>Lewin</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"elenco"},
{f:"Il metodo fenomenologico sperimentale",b:"Studiare il <strong>fenomeno percepito dai soggetti</strong> in relazione al <strong>variare degli stimoli fisici</strong> del mondo esterno.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Introspezione vs metodo fenomenologico",b:"<strong>Introspezione</strong>: <strong>scompone</strong>; osservatore = sperimentatore.<br><strong>Fenomenologico</strong>: <strong>non scompone</strong>; resoconti dei soggetti + <strong>rigoroso controllo</strong> dello stimolo.",a:"Gestalt",l:"L02",c:"C10",t:"coppia"},
{f:"Le tre caratteristiche delle leggi gestaltiche",b:"<strong>Indipendenti dall'esperienza</strong> · <strong>geneticamente determinate</strong> · <strong>specie-specifiche</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"elenco"},
{f:"La qualità gestaltica",b:"La caratteristica della percezione che <strong>rimane invariata al variare degli elementi che la compongono</strong>: garantisce l'<strong>invarianza percettiva</strong>. (Von Ehrenfels; esempio della melodia trasposta.)",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Le <em>Gestalten</em>",b:"Totalità percettive organizzate <strong>dalle parti all'intero e non viceversa</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Le illusioni — definizione",b:"<strong>Errori percettivi, di memoria o di giudizio</strong> in cui l'<strong>esperienza soggettiva differisce dalla realtà oggettiva</strong>. Rendono <strong>visibile l'atto di sintesi</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"L'esperimento del fenomeno phi",b:"Camera oscurata, <strong>due fessure</strong> con luce alternata. Variabile: l'<strong>intervallo temporale</strong>. Intervallo <strong>breve</strong> → si percepisce <strong>un unico stimolo in movimento</strong>. È il <strong>movimento stroboscopico</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"L'insight — definizione",b:"Frutto di un'<strong>improvvisa e unitaria illuminazione</strong> che <strong>ristruttura gli elementi del campo fenomenico</strong>, riorganizzandoli in una struttura globale corrispondente alla soluzione.",a:"Gestalt",l:"L02",c:"C10",t:"formula"},
{f:"Insight vs prove ed errori",b:"L'insight <strong>NON procede per prove ed errori</strong>. Nel condizionamento si apprende un'<strong>associazione</strong>, senza ristrutturazione; nell'insight c'è <strong>ristrutturazione</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"coppia"},
{f:"Köhler — il setting sperimentale",b:"<strong>Scimpanzé</strong>, stanza con <strong>banane appese al soffitto</strong> e strumenti familiari (casse, funi, bastoni). L'animale li usa con una <strong>funzionalità diversa da quella originaria</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},
{f:"Lewin — la teoria di campo",b:"Il comportamento si spiega <strong>in relazione alla situazione in cui si verifica</strong> — non nel passato ma <strong>nel qui e ora</strong> — esaminando le <strong>interrelazioni persona-ambiente</strong>.",a:"Gestalt",l:"L02",c:"C10",t:"formula"},
{f:"Lewin — il campo di vita",b:"Un <strong>campo di forze</strong> rappresentato da <strong>vettori</strong> a valenza positiva o negativa: situazioni attuali, oggetti materiali e immateriali, ambiente sociale. Equilibrio → squilibrio → azione.",a:"Gestalt",l:"L02",c:"C10",t:"definizione"},

/* --- COMPORTAMENTISMO --- */
{f:"Comportamentismo — la critica a Wundt",b:"I <strong>contenuti interni della coscienza</strong> sono <strong>impossibili da osservare direttamente e da misurare obiettivamente</strong>. Non si corregge il metodo: si cambia l'oggetto.",a:"Comportamentismo",l:"L02",c:"C11",t:"perche"},
{f:"Comportamentismo — la definizione",b:"Una psicologia <strong>integralmente obiettiva</strong>, che analizza unicamente i <strong>comportamenti manifesti</strong>, in termini di <strong>associazioni stimolo-risposta</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"La <em>black box</em>",b:"L'organismo è una <strong>scatola nera</strong> in cui non è possibile entrare: si misurano <strong>solo input (S) e output (R)</strong>. Non nega che dentro accada qualcosa: nega che sia oggetto di scienza.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"La critica comportamentista all'introspezione",b:"Non è scientifica perché <strong>l'osservatore coincide con l'osservato</strong>, e questo immette <strong>soggettività</strong> nel disegno sperimentale.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"Locke — la <em>tabula rasa</em>",b:"Alla nascita la mente è una <strong>lavagna bianca</strong> su cui l'esperienza scrive: tutto è frutto dell'esperienza, <strong>nulla è innato</strong>. Opposto esatto dell'innatismo kantiano.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"I due precursori del comportamentismo",b:"<strong>Thorndike</strong> (funzionalismo, legge dell'effetto) e <strong>Pavlov</strong> (riflessologia, condizionamento classico).",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Il minimo comune denominatore di Thorndike e Pavlov",b:"1. Ricercano entrambi nell'ambito dell'<strong>apprendimento</strong><br>2. Sperimentano entrambi <strong>sugli animali</strong> → la <strong>psicologia comparata</strong> diventa metodo elettivo",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Le TRE fasi del comportamentismo",b:"<strong>Classico</strong> (1913, Watson) → <strong>Neocomportamentismo</strong> (Hull, Tolman; a parte Skinner) → <strong>Cenocomportamentismo</strong> (anni '50, Hebb).",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Le TRE posizioni epistemologiche di Watson",b:"<strong>Molecolarismo</strong> · <strong>perifericalismo</strong> · <strong>ambientalismo</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Molecolarismo",b:"Scompone il comportamento manifesto in <strong>semplici associazioni S-R</strong> — l'analogo degli «atomi della mente» di Wundt, ma applicato al <strong>comportamento</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"Perifericalismo",b:"Le cause del comportamento si indagano al più nell'attività di <strong>muscoli e nervi periferici</strong>: non si postula nemmeno l'intervento del <strong>sistema nervoso centrale</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"Ambientalismo",b:"L'<strong>input ambientale</strong> ha rilevanza decisiva nella messa in atto del comportamento. Gli esseri umani sono il <strong>prodotto delle loro esperienze di apprendimento</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"I tre argomenti di Watson",b:"<strong>Apprendimento</strong> (in primo luogo) · <strong>emozioni</strong> · <strong>pensiero</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"L'esperimento del piccolo Albert",b:"Il bambino gioca con ratti bianchi; Watson produce <strong>rumori forti</strong> durante il gioco; per <strong>associazione ripetuta</strong> il bambino impara ad aver paura dell'animale. <strong>Condizionamento classico applicato all'uomo.</strong>",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"[N.d.R.] Chi era il piccolo Albert?",b:"<strong>Non</strong> il figlio di Watson: un bambino di circa <strong>11 mesi non imparentato</strong> con lo sperimentatore. Esperimento di <strong>Watson e Rosalie Rayner, 1920</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"data"},
{f:"Neocomportamentismo — che cosa cambia",b:"Si mette in discussione il divieto di occuparsi di ciò che sta fra stimolo e risposta: si postula una <strong>variabile interveniente</strong>, l'organismo. <strong>S-O-R</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"Hull — la catena della pulsione",b:"<strong>Condizione di bisogno</strong> (serve glucosio) → <strong>tensione</strong> → <strong>spinta a ripristinare l'equilibrio</strong> → <strong>comportamento</strong> (mangiare).",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Tolman — che cosa introduce",b:"<strong>Rappresentazioni mentali interne</strong> fra S e R. <strong>Apprendimento latente</strong> e <strong>mappe cognitive</strong>: memorie organizzate in base alle <strong>relazioni spaziali</strong> dell'ambiente.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"Skinner — la collocazione",b:"<strong>Cronologicamente</strong> nel neocomportamentismo; <strong>teoricamente</strong> torna all'ortodossia <strong>watsoniana</strong> e la estremizza. Rispetto ai neocomportamentisti fa <strong>un passo indietro</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"perche"},
{f:"Skinner — la posizione sull'interiorità",b:"Non nega l'esistenza di pensieri e sentimenti, ma afferma che <strong>nessun resoconto di ciò che accade dentro il corpo potrà mai spiegare il comportamento</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"Perché «operante»?",b:"Perché il soggetto <strong>opera attivamente nell'ambiente</strong>. Oggetto: come il comportamento è <strong>forgiato dalle conseguenze che esso stesso produce sull'ambiente</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"perche"},
{f:"Condizionamento classico vs operante",b:"<strong>Classico</strong> (Pavlov): si associano <strong>due stimoli</strong>; comportamenti <strong>passivi</strong>.<br><strong>Operante</strong> (Skinner): si associano <strong>comportamento e conseguenza</strong>; comportamenti <strong>attivi</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"coppia"},
{f:"La Skinner Box",b:"Gabbia con animale <strong>deprivato di cibo</strong> e più leve, <strong>una sola</strong> collegata a un dispenser. L'animale preme a caso, trova la leva giusta, riceve <strong>rinforzo positivo</strong> → col tempo preme solo quella.",a:"Comportamentismo",l:"L02",c:"C11",t:"definizione"},
{f:"Il rinforzo — definizione",b:"La <strong>conseguenza del comportamento sull'ambiente</strong>; determina se il comportamento avrà <strong>maggiori o minori probabilità di essere ripetuto</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"[N.d.R.] Rinforzo negativo vs punizione",b:"Il <strong>rinforzo aumenta sempre</strong> la risposta: <strong>positivo</strong> = si aggiunge un gradito; <strong>negativo</strong> = si toglie uno sgradito. Ciò che <strong>riduce</strong> la risposta è la <strong>punizione</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"coppia"},
{f:"Le tre applicazioni di Skinner",b:"1. <strong>Addestramento animale</strong><br>2. <strong>Macchine per l'apprendimento</strong> (scomporre un problema complesso in problemi semplici; ogni soluzione è essa stessa un rinforzo)<br>3. <strong>Terapia comportamentale</strong> delle fobie (decondizionamento)",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Le due derive di Skinner",b:"1. Il <strong>libero arbitrio è un'illusione</strong>: le scelte sono frutto dei condizionamenti subiti.<br>2. Una <strong>società utopistica</strong> in cui il comportamento è controllato da programmi di rinforzo.",a:"Comportamentismo",l:"L02",c:"C11",t:"elenco"},
{f:"Legge dell'effetto vs condizionamento operante",b:"<strong>Statuto</strong>: una legge vs un sistema teorico completo.<br><strong>Unità</strong>: connessione S-R vs relazione risposta-conseguenza.<br><strong>Lessico</strong>: mentalistico (soddisfazione) vs funzionale.",a:"Comportamentismo",l:"L02",c:"C11",t:"coppia"},
{f:"Hebb — perché è la figura decisiva",b:"Introduce per la prima volta un <strong>modello psicofisiologico</strong>, identificando le variabili interne come <strong>attività del SNC</strong>. <strong>Per la prima volta si parla di unità mente-cervello.</strong>",a:"Comportamentismo",l:"L02",c:"C11",t:"perche"},
{f:"La legge di Hebb",b:"Se <strong>due neuroni scaricano insieme</strong>, cioè si attivano contemporaneamente, <strong>si potenziano reciprocamente</strong> e saranno portati ad attivarsi insieme anche in seguito.",a:"Comportamentismo",l:"L02",c:"C11",t:"formula"},
{f:"Legge di Hebb vs assemblee cellulari",b:"<strong>Legge di Hebb</strong>: riguarda <strong>due singoli neuroni</strong>.<br><strong>Assemblee cellulari</strong>: <strong>configurazioni ampie</strong>, circuiti diffusi nel cervello, che una volta stabilite si rafforzano. Stanno alla base dell'<strong>apprendimento</strong>.",a:"Comportamentismo",l:"L02",c:"C11",t:"coppia"},

/* --- EXCURSUS / TRASVERSALI --- */
{f:"Le due reazioni a Wundt",b:"<strong>Gestalt</strong> (1912): sbaglia a <strong>scomporre</strong> — radice <strong>Kant</strong>, innatismo.<br><strong>Comportamentismo</strong> (1913): sbaglia a studiare l'<strong>interiorità</strong> — radice <strong>Locke</strong>, empirismo.",a:"Excursus",l:"L02",c:"C12",t:"coppia"},
{f:"Le quattro figure di frontiera",b:"<strong>Thorndike</strong> (funzionalismo → comportamentismo) · <strong>Lewin</strong> (Gestalt → psicologia sociale) · <strong>Tolman</strong> e <strong>Hebb</strong> (comportamentismo → cognitivismo).",a:"Excursus",l:"L01-L02",c:"C12",t:"elenco"},
{f:"I tre precursori del cognitivismo",b:"<strong>Vygotskij</strong> (storico-culturale) · <strong>Tolman</strong> (neocomportamentismo) · <strong>Hebb</strong> (cenocomportamentismo).",a:"Excursus",l:"L01-L02",c:"C12",t:"elenco"},
{f:"Le cinque date da non sbagliare",b:"<strong>1879</strong> Wundt · <strong>1892</strong> strutturalismo · <strong>1896</strong> funzionalismo · <strong>1912</strong> Gestalt · <strong>1913</strong> comportamentismo.",a:"Excursus",l:"L01-L02",c:"A2",t:"data"},
{f:"Il nodo «unità mente-cervello» — il percorso",b:"<strong>Negato</strong> da Cartesio → <strong>abbozzato</strong> da Gall → <strong>mancante</strong> nell'emancipazione dalla medicina → <strong>rifiutato</strong> dal perifericalismo di Watson → <strong>postulato</strong> da Hebb.",a:"Excursus",l:"L01-L02",c:"C12",t:"elenco"},
{f:"Collaterale: due sensi diversi",b:"Le <strong>scuole russe</strong> sono collaterali in senso <strong>geografico</strong>; la <strong>psicoanalisi</strong> in senso <strong>epistemologico</strong>. Usare lo stesso criterio per entrambe è l'errore tipico.",a:"Excursus",l:"L01",c:"C12",t:"coppia"},
{f:"Le cinque mosse di una risposta d'esame",b:"1. <strong>Collocazione</strong> · 2. l'<strong>esigenza</strong> da cui nasce · 3. la <strong>terna</strong> oggetto-metodo-validità · 4. un <strong>esperimento</strong> o concetto tecnico · 5. il <strong>ponte</strong> verso la scuola successiva.",a:"Excursus",l:"L01-L02",c:"C12",t:"elenco"},
{f:"Il gesto che accomuna Titchener e la Scuola di Chicago",b:"<strong>Dare un nome</strong> a una scuola preesistente e <strong>sistematizzarla</strong>. Prima si fa ricerca, poi qualcuno la battezza e ne fissa i confini.",a:"Excursus",l:"L01",c:"C07",t:"perche"},
{f:"Perché il cognitivismo è l'esito del comportamentismo?",b:"Perché le tre fasi corrispondono a un'evoluzione <strong>epistemologica</strong>: riaffiora progressivamente l'attenzione all'interiorità — variabile interveniente, poi rappresentazione, poi circuito neuronale.",a:"Excursus",l:"L02",c:"C12",t:"perche"},
{f:"La domanda-chiave dell'excursus",b:"Non «che cosa viene dopo?» ma «<strong>che cosa non funzionava prima?</strong>». L'excursus ha struttura <strong>causale</strong>, non cronologica.",a:"Excursus",l:"L01-L02",c:"C12",t:"perche"}
,

/* --- COGNITIVISMO (L03) --- */
{f:"Cognitivismo — come nasce",b:"È la <strong>filiazione del cenocomportamentismo</strong>: <strong>evoluzione naturale, non reazione</strong>. È l'unica scuola del corso che non nasce contro qualcuno.",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"Cognitivismo — la definizione",b:"Una psicologia <strong>totalmente mentalistica</strong>.<br><em>Da confrontare con il comportamentismo: «psicologia integralmente obiettiva».</em>",a:"Cognitivismo",l:"L03",c:"C13",t:"formula"},
{f:"Piaget — l'esperimento della creta",b:"Due mucchietti pareggiati dal bambino; poi uno viene diviso in <strong>tante palline</strong>. Il bambino di tre anni dice che è maggiore quello con più palline → la <strong>costanza della quantità</strong> si acquisisce più tardi.",a:"Cognitivismo",l:"L03",c:"C13",t:"definizione"},
{f:"Chomsky contro Skinner — le due tesi",b:"<strong>Skinner</strong>: il linguaggio è frutto del <strong>condizionamento ambientale</strong>.<br><strong>Chomsky</strong>: gli esseri umani sono <strong>biologicamente preprogrammati</strong> per apprendere il linguaggio, grazie a <strong>regole mentali</strong>.",a:"Cognitivismo",l:"L03",c:"C13",t:"coppia"},
{f:"L'argomento decisivo di Chomsky",b:"I bambini, appena cominciano a parlare, producono <strong>frasi e parole a cui non sono mai stati esposti</strong>. Un condizionamento riproduce solo ciò che è stato presentato.",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"Bartlett — il contributo",b:"<strong>Schemi cognitivi</strong> nella memoria autobiografica: i nuovi elementi si incastrano con quelli già acquisiti. La memoria è un processo <strong>costruttivo</strong>, non passivo.",a:"Cognitivismo",l:"L03",c:"C13",t:"definizione"},
{f:"Broadbent — la teoria del filtro attentivo",b:"Nell'elaborazione c'è un <strong>filtro</strong>, un «collo di bottiglia»: l'informazione in entrata subisce una <strong>selezione rigida</strong>, e solo una piccola parte viene elaborata.",a:"Cognitivismo",l:"L03",c:"C13",t:"definizione"},
{f:"Il simposio del 1956 — i tre interventi",b:"<strong>Miller</strong>: lo <strong>span</strong> della memoria a breve termine.<br><strong>Newell e Simon</strong>: il <strong>problem solving</strong> e lo spazio problematico.<br><strong>Chomsky</strong>: la teoria del linguaggio.",a:"Cognitivismo",l:"L03",c:"C13",t:"elenco"},
{f:"Lo span di Miller",b:"Il <strong>numero di elementi</strong> che possono essere contenuti <strong>contemporaneamente</strong> nella <strong>memoria a breve termine</strong>, il magazzino che consente di manipolare l'informazione in modo consapevole.",a:"Cognitivismo",l:"L03",c:"C13",t:"definizione"},
{f:"L'unità TOTE",b:"<strong>T</strong>est → <strong>O</strong>perate → <strong>T</strong>est → <strong>E</strong>xit.<br>Schema a <strong>feedback retroattivo</strong> (Miller, Galanter, Pribram): si testa il comportamento, si modifica, si ritesta; se si è soddisfatti si esce mettendolo in atto.",a:"Cognitivismo",l:"L03",c:"C13",t:"elenco"},
{f:"Che cosa sostituisce l'unità TOTE",b:"La <strong>connessione S-R</strong> come unità di analisi. Al posto di un legame fisso c'è un <strong>ciclo con retroazione</strong>: il comportamento non è emesso, è progettato, verificato e corretto.",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"Il manifesto del cognitivismo",b:"<strong>Ulric Neisser</strong>, <em>Cognitive Psychology</em>, <strong>1967</strong>.<br><em>Ma «non fece altro che un'opera di collage» di cose già in essere.</em>",a:"Cognitivismo",l:"L03",c:"C13",t:"data"},
{f:"Il metodo simulativo — i quattro passi",b:"1. <strong>Ipotesi</strong> di funzionamento di una funzione cognitiva<br>2. <strong>Modello</strong> di funzionamento<br>3. <strong>Implementazione nel computer</strong><br>4. Se produce i risultati attesi, l'ipotesi è <strong>validata</strong>",a:"Cognitivismo",l:"L03",c:"C13",t:"elenco"},
{f:"Il pregio del metodo simulativo",b:"È <strong>ineccepibile</strong>: fornisce un <strong>controllo assoluto di tutte le variabili</strong>, perché sono controllate da una macchina.<br><em>Ed è precisamente questo pregio a generarne il limite.</em>",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"Perché cade il divieto comportamentista",b:"Perché con il computer diventa possibile <strong>verificare empiricamente qualcosa di astratto</strong>. Il divieto non è stato confutato: è diventato <strong>tecnicamente superfluo</strong>.",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"La critica ecologica — chi la fa e che cosa dice",b:"La fa <strong>Neisser stesso</strong>: la ricerca psicologica <strong>si è allontanata dalla realtà</strong>, indagando i processi cognitivi solo nell'ambito artificiale del laboratorio. Propone l'<strong>approccio ecologico</strong>.",a:"Cognitivismo",l:"L03",c:"C13",t:"perche"},
{f:"L'architettura funzionale",b:"L'oggetto della scienza cognitiva nella prima fase: la <strong>struttura astratta</strong> che permette le funzioni intellettive, <strong>prescindendo dalla sua base materiale</strong>.",a:"Cognitivismo",l:"L03",c:"C13",t:"formula"},
{f:"Il modularismo di Fodor — i tre stadi",b:"1. <strong>Trasduttori</strong>: convertono gli stimoli in rappresentazioni interne<br>2. <strong>Moduli</strong>: capsule di input, lavorano in modo <strong>automatico e parallelo</strong><br>3. <strong>Sistemi centrali</strong>: ricevono gli output dei moduli e li <strong>integrano</strong>",a:"Cognitivismo",l:"L03",c:"C13",t:"elenco"},
{f:"Il connessionismo della scienza cognitiva",b:"Primo tentativo di considerare la <strong>base materiale</strong>: l'architettura mentale come <strong>rete di unità di elaborazione omogenee</strong> che ricalcano i neuroni — unità di <strong>input</strong>, <strong>nascoste</strong>, di <strong>output</strong>.",a:"Cognitivismo",l:"L03",c:"C13",t:"definizione"},
{f:"I due connessionismi — non confonderli",b:"<strong>Thorndike</strong> (L01): connessioni <strong>situazione-risposta</strong>, dentro il funzionalismo.<br><strong>Scienza cognitiva</strong> (L03): <strong>rete di unità di elaborazione</strong>. Stessa parola, due paradigmi.",a:"Cognitivismo",l:"L03",c:"C13",t:"coppia"},

/* --- PSICOLOGIA CONTEMPORANEA (L03) --- */
{f:"Mente embodied — la catena che la giustifica",b:"I processi cognitivi si svolgono in una <strong>mente</strong> basata su un <strong>cervello</strong>, che è un <strong>organo</strong>, che fa parte di un <strong>corpo</strong> — e subisce quindi influenze non puramente cerebrali.",a:"Contemporanea",l:"L03",c:"C14",t:"perche"},
{f:"I tre corollari della mente embodied",b:"1. La mente <strong>ha un corpo</strong><br>2. Le competenze cognitive sono descrivibili solo <strong>in azione e in interazione</strong> con l'ambiente<br>3. La mente è <strong>relazionale</strong>, non una macchina di pensiero",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Il rapporto fra psicologia contemporanea e cognitivismo",b:"Il cognitivismo <strong>è tuttora in essere</strong>: non è stato superato, si è <strong>allargato</strong>.<br><em>L'errore tipico è raccontarlo come un superamento.</em>",a:"Contemporanea",l:"L03",c:"C14",t:"perche"},
{f:"Le tre prospettive del biopsicosociale",b:"<strong>Biologica</strong> · <strong>psicologica</strong> · <strong>socioculturale</strong>.<br><em>Da non confondere con le tre espansioni delle neuroscienze: cognitive, affettive, relazionali.</em>",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Prospettiva biologica — che cosa indaga",b:"<strong>Selezione naturale</strong> di tratti adattivi · <strong>predisposizioni genetiche</strong> di tratti cognitivi · <strong>meccanismi cerebrali</strong> · <strong>influenze ormonali</strong>.",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Prospettiva psicologica — che cosa indaga",b:"<strong>Paure apprese</strong> e <strong>aspettative</strong> · il substrato <strong>emotivo</strong> oltre che cognitivo · l'<strong>elaborazione cognitiva</strong> e l'interpretazione percettiva.",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Prospettiva socioculturale — che cosa indaga",b:"Presenza degli <strong>altri</strong> e dei <strong>pari</strong> · aspettative <strong>sociali, culturali, familiari</strong> · influenze dei <strong>gruppi</strong> · <strong>modelli persuasivi</strong> dell'ambiente.",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Neuroscienze comportamentali — definizione",b:"Indagano i <strong>processi cerebrali</strong> e le <strong>altre funzioni fisiologiche all'origine del comportamento</strong>. Dette anche <strong>psicologia fisiologica</strong> o <strong>psicofisiologia</strong>.",a:"Contemporanea",l:"L03",c:"C14",t:"formula"},
{f:"Lashley — che cosa cercava e che cosa trovò",b:"Cercava la <strong>zona precisa</strong> che media l'apprendimento spaziale nei ratti (labirinti + asportazione chirurgica). <strong>Non la trovò</strong>: contava la <strong>quantità</strong> di tessuto asportato, non la sede.",a:"Contemporanea",l:"L03",c:"C14",t:"definizione"},
{f:"I due limiti del metodo di Lashley",b:"1. È <strong>molto invasivo</strong> (rimozione chirurgica in animali)<br>2. <strong>Non è utilizzabile nell'uomo</strong>",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},
{f:"Neuroimmagine strutturale vs funzionale",b:"<strong>Strutturale</strong>: com'è fatto il cervello — <strong>TAC</strong>, <strong>risonanza magnetica</strong>.<br><strong>Funzionale</strong>: che cosa sta facendo — <strong>PET</strong>, <strong>risonanza magnetica funzionale</strong>.",a:"Contemporanea",l:"L03",c:"C14",t:"coppia"},
{f:"Il salto decisivo della neuroimmagine funzionale",b:"Studiare il legame fra <strong>processi cognitivi superiori e attività cerebrale</strong> <strong>in vivo, nell'uomo, mentre esegue compiti</strong>. Dove Lashley doveva distruggere, oggi si osserva.",a:"Contemporanea",l:"L03",c:"C14",t:"perche"},
{f:"Le tre espansioni delle neuroscienze",b:"Neuroscienze <strong>cognitive</strong> (funzioni superiori) · <strong>affettive</strong> (processi emotivi) · <strong>relazionali</strong> (processi con le altre persone).",a:"Contemporanea",l:"L03",c:"C14",t:"elenco"},

/* --- DISCIPLINE COLLATERALI (L03) --- */
{f:"Genetica del comportamento",b:"Studia <strong>come le tendenze comportamentali siano influenzate da fattori genetici</strong>: aggressività, timidezza, predisposizione a patologie mentali.",a:"Discipline collaterali",l:"L03",c:"C15",t:"definizione"},
{f:"Lo studio sui gemelli — perché funziona",b:"Gli <strong>omozigoti</strong> (che condividono la maggior parte del genoma) si somigliano <strong>anche se allevati in ambienti diversi</strong>; negli <strong>eterozigoti</strong>, che ne condividono meno, alcune similarità non si osservano.",a:"Discipline collaterali",l:"L03",c:"C15",t:"perche"},
{f:"Epigenetica",b:"Analizza i <strong>cambiamenti che intervengono nel genotipo</strong> che il sistema nervoso sviluppa <strong>in seguito all'interazione con l'ambiente</strong>. <strong>Dirime</strong> il dibattito natura/cultura.",a:"Discipline collaterali",l:"L03",c:"C15",t:"definizione"},
{f:"Psicologia evoluzionistica — la tesi",b:"La mente umana è un <strong>insieme di moduli specializzati</strong> atti a risolvere i problemi che i nostri antenati hanno affrontato <strong>per milioni di anni</strong>.",a:"Discipline collaterali",l:"L03",c:"C15",t:"formula"},
{f:"Psicologia umanistica",b:"<strong>Maslow</strong> e <strong>Rogers</strong>: contano le <strong>potenzialità positive</strong> della persona, che funziona al meglio in un <strong>ambiente stimolante e positivo</strong>. → <strong>psicologia della salute</strong>.",a:"Discipline collaterali",l:"L03",c:"C15",t:"definizione"},
{f:"Umanistica vs psicodinamica",b:"<strong>Freud</strong>: indaga la <strong>patologia</strong>, il sintomo, il conflitto.<br><strong>Maslow e Rogers</strong>: indagano le <strong>potenzialità positive</strong> e il funzionamento ottimale.",a:"Discipline collaterali",l:"L03",c:"C15",t:"coppia"},
{f:"La cultura — definizione",b:"L'insieme di <strong>valori, credenze, comportamenti e tradizioni</strong> durevoli nel tempo, condivisi da gruppi sociali e <strong>trasmessi da una generazione all'altra</strong>.",a:"Discipline collaterali",l:"L03",c:"C15",t:"formula"},
{f:"Il punto teorico sulla cultura",b:"<strong>Non ha base biologica né genetica</strong> — eppure <strong>viene trasmessa ugualmente</strong>. Esiste un canale fra generazioni che non passa dai geni.",a:"Discipline collaterali",l:"L03",c:"C15",t:"perche"},
{f:"Le regole di esibizione delle emozioni",b:"Le emozioni di base sono <strong>biologicamente determinate</strong> e universali; ma alcune <strong>regole di esibizione</strong> sono <strong>cultura-specifiche</strong>. È il biopsicosociale in un solo esempio.",a:"Discipline collaterali",l:"L03",c:"C15",t:"definizione"},
{f:"Socioculturale ≠ storico-culturale",b:"<strong>Psicologia socioculturale</strong>: approccio <strong>contemporaneo</strong> che affianca le neuroscienze (L03).<br><strong>Scuola storico-culturale</strong>: <strong>Vygotskij</strong>, Russia dopo il 1917 (L01).",a:"Discipline collaterali",l:"L03",c:"C15",t:"coppia"},
{f:"Perché oggi la psicologia «non è settoriale»",b:"Utilizza <strong>tantissime altre discipline</strong> per rispondere ai propri quesiti. È il rovesciamento della strategia di Wundt, che si definiva <strong>restringendo</strong>: un oggetto, un metodo, un laboratorio.",a:"Discipline collaterali",l:"L03",c:"C15",t:"perche"},

/* --- TRASVERSALI L01-L03 --- */
{f:"Neisser — il doppio ruolo",b:"Scrive il <strong>manifesto</strong> del cognitivismo (1967) <em>e</em> ne diventa il <strong>primo critico</strong> con la critica ecologica. È l'unico nel corso a criticare la scuola di cui aveva scritto il manifesto.",a:"Excursus",l:"L03",c:"C13",t:"perche"},
{f:"Innatismo vs empirismo — le tre comparse",b:"1. <strong>Kant / Locke</strong> → Gestalt e comportamentismo (L02)<br>2. <strong>Chomsky / Skinner</strong> → il linguaggio (L03)<br>3. <strong>Natura / cultura</strong> → genetica del comportamento, che l'<strong>epigenetica</strong> dirime (L03)",a:"Excursus",l:"L01-L03",c:"C15",t:"elenco"},
{f:"L'unità mente-cervello — il percorso completo",b:"<strong>Negata</strong> da Cartesio → <strong>abbozzata</strong> da Gall → <strong>mancante</strong> nell'emancipazione dalla medicina → <strong>rifiutata</strong> dal perifericalismo → <strong>postulata</strong> da Hebb → <strong>principale oggetto di studio</strong> delle neuroscienze.",a:"Excursus",l:"L01-L03",c:"C14",t:"elenco"},
{f:"Le tre volte in cui una scuola nasce da un nome",b:"<strong>Titchener</strong> sistematizza Wundt e lo chiama strutturalismo · la <strong>Scuola di Chicago</strong> emette il manifesto funzionalista · <strong>Neisser</strong> pubblica <em>Cognitive Psychology</em>. Prima si fa ricerca, poi qualcuno la battezza.",a:"Excursus",l:"L01-L03",c:"C13",t:"perche"}
,

/* --- METODO SCIENTIFICO (L04) --- */
{f:"Psicologia ingenua — definizione",b:"Forma <strong>imprescindibile</strong> di sapere per cui ognuno dà spiegazioni ai comportamenti <strong>senza porsi la domanda sulla loro esattezza</strong>. Ha <strong>valore pragmatico rilevante</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"definizione"},
{f:"Le tre fonti di errore del senso comune",b:"1. <strong>Giudizio retrospettivo</strong> — bravi a spiegare, non a prevedere<br>2. <strong>Eccessiva fiducia in sé</strong> — esperimento di Goranson<br>3. <strong>Schemi ricorrenti</strong> — nessi causali in eventi casuali",a:"Metodo scientifico",l:"L04",c:"C16",t:"elenco"},
{f:"L'esperimento di Goranson",b:"Tre anagrammi <strong>con la soluzione accanto</strong>: i soggetti stimano <strong>dieci secondi</strong>. Un anagramma <strong>senza</strong> soluzione richiede <strong>tre minuti</strong>. Avere la soluzione rende il problema <strong>retrospettivamente facile</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"definizione"},
{f:"Perché la psicologia è un caso difficile",b:"Perché <strong>la mente non è né direttamente osservabile né quantificabile</strong>. Da qui il <strong>ritardo</strong> e le <strong>riserve</strong>: elevato grado di soggettività e indeterminazione.",a:"Metodo scientifico",l:"L04",c:"C16",t:"perche"},
{f:"Einstein e Heisenberg — il riavvicinamento",b:"<strong>Einstein</strong>: le osservazioni sono sempre <strong>relative al punto di vista di un osservatore</strong>.<br><strong>Heisenberg</strong>: la misura di due variabili coniugate ha un'<strong>incertezza ineliminabile</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"coppia"},
{f:"I quattro assunti del metodo scientifico",b:"1. <strong>Determinismo</strong><br>2. <strong>Empirismo</strong><br>3. <strong>Invarianza</strong><br>4. <strong>Operazionalizzazione</strong> — il più importante per la psicologia",a:"Metodo scientifico",l:"L04",c:"C16",t:"elenco"},
{f:"Determinismo — enunciato",b:"Gli effetti osservati <strong>non sono dovuti al caso</strong> ma sempre riconducibili a una <strong>causa</strong>: ogni risposta è l'esito di una <strong>catena causale</strong>. È l'assunto <strong>epistemologico di base</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"formula"},
{f:"Empirismo — la clausola che si dimentica",b:"Non basta la verifica empirica: <strong>l'ipotesi non è precostituita</strong>. Origina da osservazioni empiriche o da teorie <strong>già dimostrate empiricamente</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"formula"},
{f:"Invarianza — enunciato e conseguenza",b:"<strong>A parità di tutte le condizioni</strong>, la combinazione degli stessi fattori produce <strong>sempre lo stesso evento</strong>. È ciò che consente <strong>induzioni prospettiche e previsioni</strong>, e giustifica la <strong>replicabilità</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"formula"},
{f:"Operazionalizzazione — definizione",b:"Ogni concetto contenuto in una teoria va <strong>tradotto in un formato replicabile e misurabile</strong>. Comprende la <strong>definizione operativa</strong> e gli <strong>step operativi</strong> per osservarlo.",a:"Metodo scientifico",l:"L04",c:"C16",t:"formula"},
{f:"Le due proprietà della definizione operativa",b:"<strong>Valida</strong> — misura solo ciò che dichiara di misurare.<br><strong>Univoca</strong> — si riferisce a <strong>processi unici e non plurimi</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"elenco"},
{f:"Il controesempio del pensiero riflessivo",b:"Misurarlo contando il tempo con <strong>gli occhi chiusi</strong> non è valido: gli occhi chiusi possono indicare che il soggetto <strong>sta dormendo</strong>. La misura esprimerebbe un processo <strong>plurimo</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"perche"},
{f:"Perché ogni definizione operativa è approssimata",b:"È <strong>matematicamente impossibile escludere</strong> che una misura colga anche altri fattori. Ogni definizione operativa è quindi un'<strong>approssimazione al vero</strong>: <strong>mai una verità assoluta</strong>.",a:"Metodo scientifico",l:"L04",c:"C16",t:"perche"},
{f:"Validità, fidabilità, sensibilità — a che cosa si riferiscono",b:"<strong>Validità</strong> → la <strong>definizione operativa</strong>.<br><strong>Fidabilità</strong> → lo <strong>strumento</strong>: stesso risultato ogni volta.<br><strong>Sensibilità</strong> → lo <strong>strumento</strong>: rileva piccolissime quantità.",a:"Metodo scientifico",l:"L04",c:"C17",t:"coppia"},

/* --- PROCESSO DI RICERCA (L04) --- */
{f:"Ricerca di base e ricerca applicata",b:"Differiscono per il <strong>problema di partenza</strong>, ma <strong>il processo di ricerca è totalmente identico</strong>. La distinzione riguarda la motivazione, non lo statuto epistemologico.",a:"Processo di ricerca",l:"L04",c:"C17",t:"coppia"},
{f:"Le quattro fasi del processo di ricerca",b:"1. <strong>Identificazione del problema</strong><br>2. <strong>Spiegazione teorica</strong> → ipotesi<br>3. <strong>Ricerca empirica</strong><br>4. <strong>Comunicazione dei risultati</strong> → e si torna alla 1",a:"Processo di ricerca",l:"L04",c:"C17",t:"elenco"},
{f:"Perché il processo è circolare",b:"Perché la ricerca è una <strong>continua approssimazione al vero</strong> e non arriva mai a una verità assoluta. Si torna alla tappa iniziale <strong>a un livello più profondo</strong>.",a:"Processo di ricerca",l:"L04",c:"C17",t:"perche"},
{f:"Che cos'è un problema di ricerca (Popper)",b:"Una <strong>contraddizione fra affermazioni</strong> contenute in una teoria o in determinati fatti. Genera nel ricercatore un'<strong>idea anticipatoria</strong>.",a:"Processo di ricerca",l:"L04",c:"C17",t:"definizione"},
{f:"Le cinque caratteristiche del ricercatore",b:"<strong>Curioso</strong> · <strong>creativo</strong> (collega fattori sconnessi) · <strong>intuitivo</strong> · <strong>aperto mentalmente</strong> · <strong>scettico</strong>",a:"Processo di ricerca",l:"L04",c:"C17",t:"elenco"},
{f:"Le due modalità con cui la letteratura genera problemi",b:"<strong>Euristica</strong> — una teoria genera enorme interesse e attira studi (es. l'asse intestino-cervello).<br><strong>Sistematica</strong> — una teoria fa <strong>affermazioni esplicite direttamente verificabili</strong>.",a:"Processo di ricerca",l:"L04",c:"C17",t:"coppia"},
{f:"Teoria e ipotesi — la distinzione",b:"<strong>Teoria</strong>: insieme organizzato di frasi che <strong>spiegano</strong> un fenomeno.<br><strong>Ipotesi</strong>: <strong>predizione testabile</strong>, in forma <strong>se-allora</strong>.<br><em>Una teoria non si testa direttamente: si testano le ipotesi che se ne derivano.</em>",a:"Processo di ricerca",l:"L04",c:"C17",t:"coppia"},
{f:"L'argomento dei cigni (Popper)",b:"Nessun numero di cigni bianchi rende vera l'affermazione «tutti i cigni sono bianchi»: è vera <strong>finché non si dimostra che è falsa</strong>. Un solo cigno nero la abbatte.",a:"Processo di ricerca",l:"L04",c:"C17",t:"formula"},
{f:"Il criterio di falsificabilità",b:"<strong>È scientifica ogni teoria confutabile.</strong> Il vero compito dello scienziato è <strong>falsificare</strong> le teorie esistenti, perché individuare l'errore avvicina alla verità.",a:"Processo di ricerca",l:"L04",c:"C17",t:"formula"},
{f:"Perché Popper critica la psicoanalisi",b:"Dal punto di vista logico «<strong>non fa una piega</strong>», è perfetta — ma <strong>non consente alcuna falsificazione</strong>. Una teoria che spiega qualunque esito non è confermata da nessun esito.",a:"Processo di ricerca",l:"L04",c:"C17",t:"perche"},
{f:"Le tre caratteristiche difficili dell'essere umano",b:"<strong>Complessità</strong> — fenomeni multideterminati<br><strong>Variabilità</strong> — fra individui e <em>entro</em> lo stesso individuo<br><strong>Reattività</strong>",a:"Processo di ricerca",l:"L04",c:"C17",t:"elenco"},
{f:"Le tre dimensioni della tassonomia delle strategie",b:"<strong>Metodo di ricerca</strong> (sperimentale &gt; correlazionale &gt; descrittivi) · <strong>tecnica di raccolta dei dati</strong> (oggettiva / soggettiva) · <strong>ambiente</strong> (laboratorio / campo)",a:"Processo di ricerca",l:"L04",c:"C17",t:"elenco"},
{f:"Statistica descrittiva e inferenziale",b:"<strong>Descrittiva</strong>: <strong>non</strong> consente inferenze, descrive l'andamento dei dati (media, deviazione standard).<br><strong>Inferenziale</strong>: consente <strong>generalizzazioni</strong> dal campione alla popolazione (ANOVA, correlazione).",a:"Processo di ricerca",l:"L04",c:"C17",t:"coppia"},
{f:"I cinque contenuti del consenso informato",b:"1. <strong>Scopo e procedure</strong> (laddove comunicabile)<br>2. potenziali <strong>benefici</strong><br>3. potenziali <strong>rischi</strong><br>4. <strong>diritto di rifiuto o ritiro</strong> in qualsiasi momento<br>5. <strong>tutela dei dati sensibili</strong>",a:"Processo di ricerca",l:"L04",c:"C17",t:"elenco"},

/* --- VARIABILI (L05) --- */
{f:"Variabile — definizione",b:"Un'entità che <strong>varia</strong>. Virtualmente <strong>tutto ciò che può variare</strong> — quantitativamente o anche solo come <strong>presente/assente</strong> — può essere definito variabile.",a:"Variabili",l:"L05",c:"C18",t:"definizione"},
{f:"Le quattro scale di misura",b:"<strong>Nominale</strong> (solo diversità) → <strong>ordinale</strong> (+ ordine) → <strong>intervalli equivalenti</strong> (+ intervallo costante, zero arbitrario) → <strong>rapporti equivalenti</strong> (+ rapporti, zero naturale).<br><em>Gerarchia cumulativa.</em>",a:"Variabili",l:"L05",c:"C18",t:"elenco"},
{f:"L'albero decisionale delle scale",b:"<strong>Ordinabili?</strong> No → nominale.<br>Sì → <strong>intervalli equivalenti?</strong> No → ordinale.<br>Sì → <strong>lo zero è assenza?</strong> No → intervalli. Sì → rapporti.",a:"Variabili",l:"L05",c:"C18",t:"elenco"},
{f:"Zero arbitrario e zero naturale",b:"<strong>Arbitrario</strong>: Celsius, Fahrenheit — non si possono confrontare le scale (20°C non è il doppio di 10°C).<br><strong>Naturale</strong>: Kelvin, peso, tempo — il rapporto <strong>non dipende dall'unità</strong>.",a:"Variabili",l:"L05",c:"C18",t:"coppia"},
{f:"Variabili qualitative e quantitative",b:"<strong>Qualitative</strong> (nominale, ordinale): producono <strong>frequenze</strong>.<br><strong>Quantitative</strong> o metriche (intervalli, rapporti): producono <strong>punteggi</strong> e informano sull'<strong>intensità</strong>.",a:"Variabili",l:"L05",c:"C18",t:"coppia"},
{f:"Perché la scala di misura è decisiva",b:"Perché da essa dipende la <strong>scelta dei test statistici</strong>: sbagliarla produce <strong>risultati non interpretabili</strong>. Non è un errore di eleganza, <strong>invalida lo studio</strong>.",a:"Variabili",l:"L05",c:"C18",t:"perche"},
{f:"Variabile indipendente e dipendente",b:"<strong>Indipendente (x)</strong>: gli stimoli o eventi che si presuppone siano la <strong>causa</strong>.<br><strong>Dipendente (y)</strong>: gli eventi che <strong>risentono dell'effetto</strong> della VI.",a:"Variabili",l:"L05",c:"C18",t:"coppia"},
{f:"VI manipolabili e non manipolabili",b:"<strong>Manipolabili</strong>: caffeina, dose di un farmaco, intensità della luce.<br><strong>Non manipolabili</strong>: QI, età, appartenenza religiosa, affiliazione politica. → con queste si ha un <strong>quasi esperimento</strong>.",a:"Variabili",l:"L05",c:"C18",t:"coppia"},

/* --- REVISIONE DELLA LETTERATURA (L05) --- */
{f:"I tre livelli di revisione della letteratura",b:"<strong>Narrativa</strong> → <strong>sistematica</strong> → <strong>meta-analisi</strong>. Insiemi <strong>concentrici</strong>: più si stringe, più si è precisi.",a:"Variabili",l:"L05",c:"C18",t:"elenco"},
{f:"Revisione narrativa — limite",b:"Il <strong>processo di selezione delle fonti</strong> risponde a <strong>criteri soggettivi</strong>: rappresenta solo una parte delle conoscenze. Esempio: i <strong>capitoli di un manuale</strong>.",a:"Variabili",l:"L05",c:"C18",t:"definizione"},
{f:"Che cosa rende sistematica una revisione sistematica",b:"<strong>Criteri rigorosi e stabiliti a priori</strong>, riportati in uno <strong>specifico protocollo</strong>: minimizza le distorsioni e rende la revisione <strong>replicabile</strong> da altri.",a:"Variabili",l:"L05",c:"C18",t:"perche"},
{f:"Meta-analisi — che cos'è e quando NON si fa",b:"Revisione sistematica <strong>+ tecniche statistiche</strong> per combinare dati di studi indipendenti → <strong>stima numerica dell'effetto</strong>.<br><em>Fuorviante se c'è troppa <strong>eterogeneità</strong>: serve convergenza.</em>",a:"Variabili",l:"L05",c:"C18",t:"definizione"},

/* --- METODI DESCRITTIVI (L05) --- */
{f:"Perché si comincia dalla descrizione",b:"Un fenomeno, <strong>prima di analizzarne i nessi causali, va descritto</strong>. Prima di trasportarlo in un ambiente artificiale bisogna sapere come funziona in quello <strong>naturale</strong>.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"perche"},
{f:"Studio dei casi — bilancio",b:"<strong>+</strong> studia da vicino fenomeni <strong>rari</strong>; può <strong>falsificare</strong> una teoria; è fonte di idee.<br><strong>−</strong> risultati solo <strong>descritti</strong>, non generalizzabili; casi <strong>atipici</strong> fuorvianti.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"coppia"},
{f:"Il paradosso dello studio dei casi",b:"Ha il <strong>minimo potere probatorio</strong> e il <strong>massimo potere confutatorio</strong>: basta un caso per falsificare una legge generale, mentre nessun numero di casi la dimostra.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"perche"},
{f:"Le tre coppie del metodo osservativo",b:"<strong>Controllata / naturalistica</strong> (ambiente)<br><strong>Diretta / indiretta</strong> (tempo)<br><strong>Qualitativa / sistematica</strong> (codifica)<br><em>Sono indipendenti e si combinano.</em>",a:"Metodi descrittivi",l:"L05",c:"C19",t:"elenco"},
{f:"I due problemi del metodo osservativo",b:"1. <strong>Interferenza dell'osservatore</strong> — e non si risolve con l'indiretta: la telecamera è comunque nota<br>2. <strong>Soggettività del ricercatore</strong> nell'interpretare",a:"Metodi descrittivi",l:"L05",c:"C19",t:"elenco"},
{f:"La sistematizzazione dell'osservazione",b:"<strong>Categorie comportamentali prefissate</strong> e <strong>regole di corrispondenza</strong> descritte in <strong>manuali di codifica</strong>. Risponde alla soggettività del ricercatore.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"definizione"},
{f:"Esposizione preventiva allo sperimentatore",b:"Il ricercatore resta a lungo nel contesto naturalistico; si instaura un'<strong>abituazione</strong> e i soggetti lo considerano <strong>parte del contesto</strong>. Tecnica di <strong>Jane Goodall</strong>.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"definizione"},
{f:"I tre esempi di osservazione",b:"<strong>Specchio unidirezionale</strong> — controllata, indiretta (diadi madre-bambino)<br><strong>EAR</strong> — registrazioni campionate nel tempo<br><strong>Jane Goodall</strong> — diretta partecipante",a:"Metodi descrittivi",l:"L05",c:"C19",t:"elenco"},
{f:"Popolazione e campione",b:"<strong>Popolazione</strong>: <strong>tutti</strong> gli individui rispetto ai quali si è interessati.<br><strong>Campione</strong>: un <strong>sottoinsieme</strong> della popolazione.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"coppia"},
{f:"La regola del campionamento",b:"<strong>Meglio un campione piccolo ma rappresentativo che grande e non rappresentativo.</strong> La numerosità aiuta, ma la <strong>rappresentatività conta di più</strong>.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"formula"},
{f:"Perché gli exit poll sbagliano",b:"Chi esce dal seggio <strong>in quel momento</strong> non è un campione rappresentativo dell'elettorato: dipende dall'orario e dal tipo di elezione. Campione enorme e inutile.",a:"Metodi descrittivi",l:"L05",c:"C19",t:"perche"},
{f:"I tre problemi dell'inchiesta",b:"1. <strong>Rappresentatività del campione</strong><br>2. <strong>Formulazione delle domande</strong> («gettito fiscale» vs «tasse»)<br>3. <strong>Desiderabilità sociale</strong> e riluttanza dei partecipanti",a:"Metodi descrittivi",l:"L05",c:"C19",t:"elenco"},

/* --- CORRELAZIONALE (L06) --- */
{f:"Metodo correlazionale — che cosa aggiunge e che cosa no",b:"<strong>Aggiunge</strong>: la misura <strong>quantitativa</strong> dell'associazione.<br><strong>Non aggiunge</strong>: nessuna <strong>manipolazione</strong>, nessun <strong>controllo</strong> sulla situazione.",a:"Correlazionale",l:"L06",c:"C20",t:"coppia"},
{f:"Le due ragioni per cui la correlazione non è causalità",b:"1. <strong>Bidirezionalità del nesso</strong> — x→y o y→x?<br>2. <strong>Terza variabile</strong> non osservata che spiega entrambe",a:"Correlazionale",l:"L06",c:"C20",t:"elenco"},
{f:"Il coefficiente r — le due informazioni",b:"<strong>Il segno</strong> dà la <strong>direzione</strong>: + positiva (alti con alti), − negativa (alti con bassi).<br><strong>Il valore</strong> dà la <strong>forza</strong>: da perfetta a prossima a zero.",a:"Correlazionale",l:"L06",c:"C20",t:"coppia"},
{f:"I tre grafici di dispersione della lezione",b:"y sempre = <strong>voto all'esame</strong>.<br><strong>Ore di studio</strong> → positiva<br><strong>Mele consumate</strong> → nessuna correlazione, r ≈ 0<br><strong>Ore di TV</strong> → negativa",a:"Correlazionale",l:"L06",c:"C20",t:"elenco"},

/* --- SPERIMENTALE (L06) --- */
{f:"Perché il metodo sperimentale è il metodo per eccellenza",b:"È <strong>l'unico</strong> che rispetta <strong>tutti e quattro gli assunti</strong>: determinismo, empirismo, invarianza, operazionalizzazione.",a:"Sperimentale",l:"L06",c:"C20",t:"perche"},
{f:"Le due condizioni per stabilire un nesso causale",b:"1. La <strong>manipolazione</strong> elimina la <strong>bidirezionalità</strong><br>2. Il <strong>controllo delle altre variabili</strong> elimina la <strong>terza variabile</strong><br><em>Sono le due obiezioni al correlazionale, prese una per una.</em>",a:"Sperimentale",l:"L06",c:"C20",t:"elenco"},
{f:"Le tre variabili sperimentali",b:"<strong>Indipendente x</strong> — manipolata, la causa, ha <strong>livelli</strong><br><strong>Dipendente y</strong> — misurata, l'effetto, dev'essere <strong>quantitativa</strong><br><strong>Di confusione z</strong> — va <strong>conosciuta</strong> per essere controllata",a:"Sperimentale",l:"L06",c:"C20",t:"elenco"},
{f:"Scelta casuale ≠ scelta a caso",b:"La <strong>scelta casuale</strong> è <strong>controllata</strong>: bilancia il genere, esclude patologie, mantiene le caratteristiche tipiche della popolazione. Prendere «i primi che capitano» è tutt'altro.",a:"Sperimentale",l:"L06",c:"C20",t:"coppia"},
{f:"Disegno tra i soggetti vs entro i soggetti",b:"<strong>Tra</strong>: soggetti diversi, una condizione ciascuno. + pulito sullo strumento, − serve campione ampio. Es. <strong>trasversale</strong>.<br><strong>Entro</strong>: un gruppo, tutte le condizioni. + più misurazioni, − <strong>sensibilizzazione</strong>. Es. <strong>longitudinale</strong>.",a:"Sperimentale",l:"L06",c:"C20",t:"coppia"},
{f:"Validità interna e validità ecologica",b:"<strong>Interna</strong>: quanto si è sicuri che la relazione causale sia <strong>veramente quella</strong>. In laboratorio è <strong>massima</strong>.<br><strong>Ecologica</strong>: quanto vale in ambiente naturale. In laboratorio è <strong>bassa</strong> — il vero limite.",a:"Sperimentale",l:"L06",c:"C20",t:"coppia"},
{f:"Quasi esperimento",b:"Quando la VI <strong>non è manipolabile</strong> — per esempio le <strong>differenze di genere</strong> — la divisione dei gruppi è <strong>data a priori</strong> e manca il <strong>controllo assoluto</strong>.",a:"Sperimentale",l:"L06",c:"C20",t:"definizione"},
{f:"Ipotesi alternativa e ipotesi nulla",b:"<strong>Alternativa</strong>: x e y <strong>sono</strong> legate da un nesso causale (è l'ipotesi sperimentale).<br><strong>Nulla</strong>: x e y <strong>non</strong> sono legate.",a:"Sperimentale",l:"L06",c:"C20",t:"coppia"},
{f:"Errore di primo e di secondo tipo",b:"<strong>I tipo (α)</strong>: nulla dichiarata <strong>falsa</strong> quando è <strong>vera</strong>.<br><strong>II tipo (β)</strong>: nulla dichiarata <strong>vera</strong> quando è <strong>falsa</strong>.<br><em>β diminuisce se α aumenta: non si minimizzano entrambi.</em>",a:"Sperimentale",l:"L06",c:"C20",t:"coppia"},
{f:"I tre esempi sperimentali della lezione",b:"<strong>Rumore</strong> e apprendimento (uomo)<br><strong>Propranololo</strong> e stress (scimmie)<br><strong>Arricchimento ambientale</strong> e neuroplasticità (ratti)",a:"Sperimentale",l:"L06",c:"C20",t:"elenco"},

/* --- PUBBLICAZIONE (L07) --- */
{f:"Che cosa rende scientifica una pubblicazione",b:"La <strong>revisione tra pari</strong>, che valuta il contenuto <strong>ex ante</strong>. Nelle pubblicazioni non scientifiche la valutazione è <strong>ex post</strong>.",a:"Pubblicazione",l:"L07",c:"C21",t:"perche"},
{f:"Gli atti di congresso",b:"Presentazione <strong>orale</strong> (simposi, talk) o <strong>poster</strong>. <strong>Non</strong> vera peer review: un <strong>comitato scientifico</strong> valuta preventivamente gli <strong>abstract</strong>.",a:"Pubblicazione",l:"L07",c:"C21",t:"definizione"},
{f:"Le cinque tipologie di articolo",b:"<strong>Ricerca originale</strong> · <strong>revisione della letteratura</strong> · <strong>case report</strong> · <strong>trial clinico</strong> · <strong>commento</strong>",a:"Pubblicazione",l:"L07",c:"C21",t:"elenco"},
{f:"Che cosa valuta l'editore (e che cosa no)",b:"<strong>Valuta</strong>: adeguatezza formale, documenti, grafica, permessi etici.<br><strong>Non valuta</strong>: la scientificità — è compito dei revisori. Può rifiutare un lavoro <strong>valido</strong> se la rivista è satura.",a:"Pubblicazione",l:"L07",c:"C21",t:"coppia"},
{f:"I revisori — chi sono e come lavorano",b:"<strong>Ricercatori come gli autori</strong>, in genere <strong>due o quattro</strong>, anonimi. Il lavoro <strong>non è retribuito</strong> ma è un <strong>onore</strong>. Valutano soprattutto i <strong>metodi</strong>: si può <strong>replicare</strong> lo studio?",a:"Pubblicazione",l:"L07",c:"C21",t:"definizione"},
{f:"La struttura dell'articolo scientifico",b:"Titolo · autori · affiliazioni · <strong>parole chiave</strong> · <strong>abstract</strong> · introduzione · <strong>metodi</strong> · risultati · discussione e conclusioni · bibliografia · materiale supplementare",a:"Pubblicazione",l:"L07",c:"C21",t:"elenco"},
{f:"Le tre posizioni d'autore che contano",b:"<strong>Primo</strong>: responsabile del <strong>disegno sperimentale</strong><br><strong>Ultimo</strong>: <strong>supervisore</strong> del gruppo o chi mette i fondi<br><strong>Corresponding</strong>: rapporti con l'editore — in genere il primo o l'ultimo",a:"Pubblicazione",l:"L07",c:"C21",t:"elenco"},
{f:"Risultati e discussione — la differenza di stile",b:"<strong>Risultati</strong>: stile <strong>descrittivo</strong> — si descrive, non si spiega.<br><strong>Discussione</strong>: stile <strong>argomentativo</strong> — si spiega alla luce della letteratura.",a:"Pubblicazione",l:"L07",c:"C21",t:"coppia"},
{f:"Media e deviazione standard",b:"Sono statistiche <strong>descrittive</strong>. La <strong>deviazione standard</strong> tiene conto della <strong>variabilità</strong> interna al gruppo: più è <strong>bassa</strong>, meno variabilità.",a:"Pubblicazione",l:"L07",c:"C21",t:"definizione"},
{f:"Impact factor e indice H",b:"<strong>Impact factor</strong>: prestigio di una <strong>rivista</strong>, in base alle citazioni dei lavori dei <strong>due anni precedenti</strong>.<br><strong>Indice H</strong>: l'equivalente per il <strong>singolo ricercatore</strong>.",a:"Pubblicazione",l:"L07",c:"C21",t:"coppia"},
{f:"Accesso chiuso e accesso aperto",b:"<strong>Chiuso</strong>: paga <strong>l'utente</strong> che legge.<br><strong>Aperto</strong>: paga <strong>il ricercatore</strong> che pubblica — l'articolo diventa gratuitamente fruibile, quindi più <strong>visibile</strong>.",a:"Pubblicazione",l:"L07",c:"C21",t:"coppia"},
{f:"PubMed vs Google Scholar",b:"<strong>PubMed</strong>: gratuita, <strong>solo lavori scientifici</strong>, del National Institute of Health, aggiornata settimanalmente.<br><strong>Google Scholar</strong>: gratuito, ma contiene anche <strong>letteratura grigia</strong> non revisionata.",a:"Pubblicazione",l:"L07",c:"C21",t:"coppia"},

/* --- TRASVERSALI --- */
{f:"L'invarianza, tre volte nel corso",b:"1. È un <strong>assunto</strong> del metodo scientifico (L04)<br>2. È ciò che rende <strong>replicabile</strong> una revisione sistematica (L05)<br>3. È il criterio dominante della <strong>peer review</strong> (L07)",a:"Metodo scientifico",l:"L04-L07",c:"C21",t:"elenco"},
{f:"Le due validità in trade-off — dove ricompaiono",b:"Il conflitto fra <strong>validità interna</strong> ed <strong>ecologica</strong> è la stessa critica che <strong>Neisser</strong> muoveva al cognitivismo (L03): un metodo ineccepibile nel controllo si allontana dalla realtà.",a:"Sperimentale",l:"L03-L06",c:"C20",t:"perche"},
{f:"La scala dei livelli di costrizione",b:"<strong>Descrittivi</strong> → <strong>correlazionale</strong> → <strong>sperimentale</strong>. Misura quanto lo sperimentatore può <strong>controllare</strong> la situazione.",a:"Metodo scientifico",l:"L05-L06",c:"C19",t:"elenco"}
];
